/* ---------- Change review ---------- */
.crx{display:grid;grid-template-columns:210px 1fr;overflow:hidden;min-height:330px}
@media (max-width:720px){.crx{grid-template-columns:1fr}.crx-side{border-right:0!important;border-bottom:1px solid var(--line)}}
.crx-side{border-right:1px solid var(--line);padding:10px;display:flex;flex-direction:column;gap:6px;min-width:0}
.crx-sh{display:flex;justify-content:space-between;align-items:baseline;padding:4px 6px;font-size:12.5px}
.crx-sh b{font-weight:500}
.crx-files{display:flex;flex-direction:column;gap:2px}
.crx-f{display:flex;align-items:center;gap:8px;padding:7px 8px;border-radius:10px;font-size:12.5px;text-align:left;transition:background .25s;min-width:0}
.crx-f:hover{background:var(--row)}
.crx-f.on{background:var(--sel)}
.crx-f .nm{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-family:var(--mono);font-size:11.5px}
.crx-f .st{width:16px;height:16px;display:grid;place-items:center;color:var(--faint)}
.crx-f.kept .st{color:var(--ok)}.crx-f.undone .st{color:var(--muted)}
.crx-main{display:flex;flex-direction:column;min-width:0}
.crx-mh{display:flex;align-items:center;gap:6px;padding:10px 12px;border-bottom:1px solid var(--line)}
.crx-fn{font-size:12px;font-family:var(--mono);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0}
.crx-sp{flex:1}
.crx-diff{padding:8px 0;font-family:var(--mono);font-size:12px;line-height:1.75;overflow-x:auto}
.crx-hk{margin:0 10px 10px;border-radius:10px;overflow:auto hidden;transition:opacity .35s}
.crx-hh{display:flex;align-items:center;gap:6px;padding:4px 6px 4px 10px;font-family:var(--sans);font-size:12px;color:var(--fg2);background:var(--chip)}
.crx-hh .sp{flex:1}
.crx-hh .pill{height:24px;padding:0 9px;font-size:12px}
.crx-l{display:flex;position:relative;white-space:pre;padding-right:10px}
.crx-l .ln{width:36px;text-align:right;padding-right:10px;color:var(--faint);flex:none;user-select:none}
.crx-l.add{background:var(--ok-bg)}.crx-l.add .c::before{content:"+ ";color:var(--ok)}
.crx-l.del{background:var(--bad-bg)}.crx-l.del .c::before{content:"− ";color:var(--bad)}
.crx-l.ctx .c::before{content:"  "}
.crx-l .cm{position:absolute;left:4px;top:3px;width:18px;height:18px;border-radius:6px;background:var(--accent);color:#fff;display:grid;place-items:center;opacity:0;transform:scale(.7);transition:opacity .2s,transform .25s var(--ease)}
.crx-l:hover .cm{opacity:1;transform:none}
.crx-hk.kept .crx-l.del{display:none}.crx-hk.kept .crx-l.add{background:transparent}.crx-hk.kept .crx-l.add .c::before{content:"  "}
.crx-hk.undone .crx-l.add{display:none}.crx-hk.undone .crx-l.del{background:transparent}.crx-hk.undone .crx-l.del .c::before{content:"  "}
.crx-hk.kept .crx-hh,.crx-hk.undone .crx-hh{color:var(--muted)}
.crx-cmt{font-family:var(--sans);margin:4px 10px 6px 36px;display:flex;gap:6px;align-items:center;padding:6px;border-radius:10px;background:var(--surface);box-shadow:var(--shadow)}
.crx-cmt input{flex:1;min-width:0;border:0;outline:0;background:transparent;font:inherit;font-size:12.5px;color:var(--fg);padding:0 6px}
.crx-cmt.sent{background:var(--sel);box-shadow:none;font-size:12.5px;padding:6px 10px}

DM.def('change-review', (r, c) => {
  const F = [
    { n:'PricingCard.tsx', h:[ { t:'Use the shared button', l:[['ctx',14,'  return ('],['del',15,'    <button className="cta-old">'],['add',15,'    <Button variant="primary">'],['ctx',16,'      {plan.cta}']] }, { t:'Drop the second CTA', l:[['del',22,'    <a href="/contact">Talk to sales</a>'],['ctx',22,'  </Card>']] } ] },
    { n:'tokens.css', h:[ { t:'Raise muted text contrast', l:[['ctx',8,':root {'],['del',9,'  --text-muted: #c9cfd8;'],['add',9,'  --text-muted: #5b6472;'],['ctx',10,'  --radius-card: 16px;']] } ] },
    { n:'pricing.mdx', h:[ { t:'Move the FAQ below the table', l:[['del',31,'<FAQ />'],['ctx',31,'<CompareTable />'],['add',32,'<FAQ />']] } ] }
  ];
  const files = $('.crx-files', r), diff = $('.crx-diff', r), fn = $('.crx-fn', r);
  let add = 0, del = 0; F.forEach(f => f.h.forEach(h => h.l.forEach(l => { if (l[0] === 'add') add++; if (l[0] === 'del') del++; h.s = h.s || ''; })));
  $('.crx-tot', r).innerHTML = `<span style="color:var(--ok)">+${add}</span> <span style="color:var(--bad)">−${del}</span>`;
  files.innerHTML = F.map((f, i) => `<button class="crx-f" data-i="${i}"><span class="ft ${f.n.endsWith('tsx') ? 're' : ''}">${f.n.split('.').pop().toUpperCase()}</span><span class="nm">${f.n}</span><span class="st"><span class="dot"></span></span></button>`).join('');
  let cur = 0;
  const esc = s => s.replace(/&/g,'&amp;').replace(/</g,'&lt;');
  function fileState(i){ const hs = F[i].h, b = $$('.crx-f', files)[i]; const all = s => hs.every(h => h.s === s); b.classList.toggle('kept', all('kept')); b.classList.toggle('undone', all('undone')); $('.st', b).innerHTML = all('kept') ? I('check','xs') : all('undone') ? I('undo','xs') : hs.some(h => h.s) ? '<span class="dot" style="color:var(--accent)"></span>' : '<span class="dot"></span>'; }
  function show(i){
    cur = i; $$('.crx-f', files).forEach((b, j) => b.classList.toggle('on', j === i)); swap(fn, 'src/' + F[i].n);
    diff.innerHTML = F[i].h.map((h, k) => `<div class="crx-hk ${h.s}" data-k="${k}"><div class="crx-hh">${I('spark','xs')}<span>${h.t}</span><span class="sp"></span><button class="pill ghost hk-u">Undo</button><button class="pill soft hk-k">Keep</button></div>${h.l.map(l => `<div class="crx-l ${l[0]}"><span class="ln">${l[1]}</span><span class="c">${esc(l[2])}</span><button class="cm" aria-label="Comment on line" data-tip="Comment">${I('plus','xs')}</button></div>`).join('')}</div>`).join('');
    stagger($$('.crx-hk', diff), 70);
    $$('.crx-hk', diff).forEach(hk => { const h = F[i].h[+hk.dataset.k];
      const setS = s => { h.s = h.s === s ? '' : s; hk.className = 'crx-hk ' + h.s; fileState(i); };
      $('.hk-k', hk).onclick = () => setS('kept'); $('.hk-u', hk).onclick = () => setS('undone');
      $$('.cm', hk).forEach(b => b.onclick = () => { const ln = b.closest('.crx-l'); if (ln.nextElementSibling?.classList.contains('crx-cmt')) return;
        const box = html(`<div class="crx-cmt"><input placeholder="Ask the agent about this line"><button class="pill accent sm">Send</button></div>`); ln.after(box); enter(box); const inp = $('input', box); inp.focus();
        const send = () => { const v = inp.value.trim() || 'Why this change?'; box.className = 'crx-cmt sent'; box.innerHTML = `${I('at','xs')}<span>${esc(v)}</span>`; enter(box); };
        $('button', box).onclick = send; inp.onkeydown = e => { if (e.key === 'Enter') send(); if (e.key === 'Escape') box.remove(); }; });
    });
  }
  $$('.crx-f', files).forEach(b => b.onclick = () => show(+b.dataset.i));
  const bulk = s => { F[cur].h.forEach(h => h.s = s); fileState(cur); show(cur); if (s === 'kept' && cur < F.length - 1) c.later(500, () => show(cur + 1)); };
  $('.crx-ok', r).onclick = () => bulk('kept'); $('.crx-rej', r).onclick = () => bulk('undone');
  F.forEach((_, i) => fileState(i)); show(0);
});
